CREATE TABLE IF NOT EXISTS directory_settings (
  id BIGINT PRIMARY KEY,
  enabled BOOLEAN NOT NULL DEFAULT FALSE,
  directory_type VARCHAR(32) NOT NULL,
  protocol VARCHAR(16) NOT NULL,
  server_host VARCHAR(255) NOT NULL,
  server_port INTEGER NOT NULL,
  base_dn VARCHAR(512) NOT NULL,
  auth_type VARCHAR(32) NOT NULL,
  bind_dn VARCHAR(512),
  bind_password VARCHAR(512),
  user_filter VARCHAR(1024) NOT NULL,
  login_attribute VARCHAR(128) NOT NULL,
  email_attribute VARCHAR(128) NOT NULL,
  display_name_attribute VARCHAR(128) NOT NULL,
  allow_local_fallback BOOLEAN NOT NULL DEFAULT TRUE,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

